import java.io.*;
import java.util.*;

public class tr0_variant5 {
    private static final int MOD = 998244353;

    public static void main(String[] args) throws Exception {
        InputScanner scanner = new InputScanner(System.in);
        int n = scanner.nextInt();
        long k = scanner.nextLong();

        if (k >= n) {
            System.out.println(0);
            return;
        }

        long[] factorial = new long[n + 1];
        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = factorial[i - 1] * i % MOD;
        }

        if (k == 0) {
            System.out.println(factorial[n]);
            return;
        }

        int c = n - (int) k;
        long answer = factorial[n];
        answer = answer * modPow(factorial[c], MOD - 2) % MOD;
        answer = answer * modPow(factorial[n - c], MOD - 2) % MOD;

        long accumulated = 0;
        for (int i = 0; i <= c; i++) {
            long binomial = factorial[c] * modPow(factorial[i], MOD - 2) % MOD;
            binomial = binomial * modPow(factorial[c - i], MOD - 2) % MOD;
            long powerValue = modPow(c - i, n);
            long currentTerm = binomial * powerValue % MOD;
            if (i % 2 == 0) {
                accumulated = (accumulated + currentTerm) % MOD;
            } else {
                accumulated = (accumulated - currentTerm + MOD) % MOD;
            }
        }

        answer = answer * accumulated % MOD;
        answer = answer * 2 % MOD;
        System.out.println(answer);
    }

    private static long modPow(long base, long exponent) {
        base %= MOD;
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return result;
    }

    static class InputScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputScanner(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public InputScanner(String filePath) throws IOException {
            reader = new BufferedReader(new FileReader(filePath));
        }

        private String getNextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        public String next() throws IOException {
            return getNextToken();
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(getNextToken());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(getNextToken());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(getNextToken());
        }

        public char nextChar() throws IOException {
            return getNextToken().charAt(0);
        }

        public boolean isReady() throws IOException {
            return reader.ready();
        }

        public void delay(int milliseconds) throws InterruptedException {
            Thread.sleep(milliseconds);
        }
    }
